# Notes: Branch-distance style fitness function for bmi_category covering all return labels.
# ================================================================================

def fitness_bmi_category(chromosome, target):
    weight = chromosome[0]
    height = chromosome[1]
    if target == "invalid_height":
        return max(0.0, height)
    height_penalty = max(0.0, -height + 1e-6)
    if height > 0:
        bmi = weight / (height * height)
    else:
        bmi = 0.0
    if target == "underweight":
        return height_penalty + max(0.0, bmi - 18.5)
    if target == "normal":
        return height_penalty + max(0.0, 18.5 - bmi) + max(0.0, bmi - 25.0)
    if target == "overweight":
        return height_penalty + max(0.0, 25.0 - bmi) + max(0.0, bmi - 30.0)
    if target == "obese":
        return height_penalty + max(0.0, 30.0 - bmi)
    raise ValueError("Unknown target: " + str(target))

