# Fitness function: fitness_list_pattern
# LLM targets: ['too_short', 'sorted_with_duplicates', 'sorted_unique', 'unsorted_with_duplicates', 'unsorted_unique']
# Notes: The fitness function returns 0 exactly when the input list triggers the corresponding return label of the original function. Positive integer distances indicate how far the input is from satisfying the required conditions (length, sortedness, duplicate presence).
# ================================================================================

def fitness_list_pattern(chromosome, target):
    nums = chromosome[0]
    len_nums = len(nums)
    # distance for the "too_short" target (len < 2)
    len_dist_too_short = max(0, len_nums - 1)
    # distance for all other targets (need at least length 2)
    len_dist_other = max(0, 2 - len_nums)
    # sorted check
    is_sorted = nums == sorted(nums)
    sorted_dist = 0 if is_sorted else 1
    not_sorted_dist = 0 if not is_sorted else 1
    # duplicate check
    has_dup = len_nums != len(set(nums))
    dup_dist = 0 if has_dup else 1
    no_dup_dist = 0 if not has_dup else 1
    if target == "too_short":
        return len_dist_too_short
    elif target == "sorted_unique":
        return len_dist_other + sorted_dist + no_dup_dist
    elif target == "sorted_with_duplicates":
        return len_dist_other + sorted_dist + dup_dist
    elif target == "unsorted_unique":
        return len_dist_other + not_sorted_dist + no_dup_dist
    elif target == "unsorted_with_duplicates":
        return len_dist_other + not_sorted_dist + dup_dist
    else:
        raise ValueError("Unknown target: " + str(target))

