def fitness_number_kind(chromosome, target):
    # Extract argument
    x = chromosome[0]
    if target == "zero":
        # distance is absolute difference from 0
        distance = abs(x - 0)
        return max(0, distance)
    elif target == "even":
        # need x != 0 and x % 2 == 0
        mod_distance = 0 if x % 2 == 0 else 1
        zero_penalty = 1 if x == 0 else 0
        distance = mod_distance + zero_penalty
        return max(0, distance)
    elif target == "odd":
        # need x % 2 != 0
        distance = 0 if x % 2 != 0 else 1
        return max(0, distance)
    else:
        raise ValueError("Unknown target: {}".format(target))

