def fitness_password_strength(chromosome, target):
    s = chromosome[0]
    length = len(s)
    has_digit = any(ch.isdigit() for ch in s)
    has_upper = any(ch.isupper() for ch in s)

    if target == "weak_short":
        # Need length < 6
        return max(0, length - 5)
    elif target == "strong":
        # Need length >= 10, at least one digit, and at least one uppercase
        dist_len = max(0, 10 - length)
        dist_digit = 0 if has_digit else 1
        dist_upper = 0 if has_upper else 1
        return dist_len + dist_digit + dist_upper
    elif target == "medium":
        # Need length >= 6, (digit or upper) true, but NOT strong condition
        dist_len = max(0, 6 - length)
        dist_digit_upper = 0 if (has_digit or has_upper) else 1
        dist_not_strong = 0 if not (length >= 10 and has_digit and has_upper) else 1
        return dist_len + dist_digit_upper + dist_not_strong
    elif target == "weak_no_digit_upper":
        # Need length >= 6 and no digit and no uppercase
        dist_len = max(0, 6 - length)
        dist_digit_upper = 0 if not (has_digit or has_upper) else 1
        return dist_len + dist_digit_upper
    else:
        raise ValueError("Unknown target: " + str(target))

