# Fitness function: fitness_transaction_pattern
# LLM targets: ['empty', 'contains_zero', 'many_large_deposits', 'many_large_withdrawals', 'mixed_transactions', 'simple_pattern']
# Notes: Fitness function returns 0 only when the chromosome would cause the original function to return the specified target; otherwise returns a positive branch‑distance‑like value.
# ================================================================================

def fitness_transaction_pattern(chromosome, target):
    amounts = chromosome[0]
    length = len(amounts)
    any_zero = any(x == 0 for x in amounts)
    positives = sum(1 for x in amounts if x > 0)
    negatives = sum(1 for x in amounts if x < 0)
    total = sum(amounts)
    if target == "empty":
        return max(0, length)
    if target == "contains_zero":
        return 0 if any_zero else 1
    if target == "many_large_deposits":
        d1 = max(0, 3 - positives)
        d2 = max(0, negatives)
        d3 = max(0, 101 - total)
        return d1 + d2 + d3
    if target == "many_large_withdrawals":
        d1 = max(0, 2 - negatives)
        d2 = max(0, total + 51)
        return d1 + d2
    if target == "mixed_transactions":
        d1 = max(0, 1 - positives)
        d2 = max(0, 1 - negatives)
        return d1 + d2
    if target == "simple_pattern":
        d_len = max(0, 1 - length)
        d_zero = 0 if not any_zero else 1
        d_deposits = 0 if not (positives >= 3 and negatives == 0 and total > 100) else 1
        d_withdrawals = 0 if not (negatives >= 2 and total < -50) else 1
        d_mixed = 0 if not (positives > 0 and negatives > 0) else 1
        return d_len + d_zero + d_deposits + d_withdrawals + d_mixed
    raise ValueError("Unknown target")

