# Original function: username_category
# Fitness function: fitness_username_category
# LLM targets: ['empty', 'too_short', 'starts_with_digit', 'strong_username', 'medium_username', 'weak_username']
# Notes: Fitness function returns 0 exactly when the original function would return the specified label and positive distances otherwise.
# ================================================================================

def fitness_username_category(chromosome, target):
    username = chromosome[0]
    length = len(username)
    has_digit = any(ch.isdigit() for ch in username)
    has_upper = any(ch.isupper() for ch in username)
    has_special = any(not ch.isalnum() for ch in username)
    starts_digit = length > 0 and username[0].isdigit()

    if target == "empty":
        return max(0, length)

    elif target == "too_short":
        if length == 0:
            return 1
        return max(0, length - 4)

    elif target == "starts_with_digit":
        if length == 0:
            return 1
        return 0 if starts_digit else 1

    elif target == "strong_username":
        dist = max(0, 10 - length)
        dist += 0 if has_digit else 1
        dist += 0 if has_upper else 1
        dist += 0 if has_special else 1
        if length == 0 or length < 5 or starts_digit:
            dist += 10
        return dist

    elif target == "medium_username":
        dist = 0 if has_digit else 1
        dist += 0 if has_upper else 1
        if length >= 10 and has_digit and has_upper and has_special:
            dist += 10
        if length == 0 or length < 5 or starts_digit:
            dist += 10
        return dist

    elif target == "weak_username":
        if length == 0 or length < 5 or starts_digit:
            return 1
        if length >= 10 and has_digit and has_upper and has_special:
            return 1
        if has_digit and has_upper:
            return 1
        return 0

    else:
        raise ValueError("Unknown target")

